-- 0152_renter_portal_design.sql
-- The renter portal's new design (docs/changes/2026-10-24-renter-portal-design.md). The owner, October 24, 2026: "When
-- a renter signs in and is looking at their active rentals, it should look nice. Maybe there should be a picture of the
-- car they are renting." The portal pages are redesigned in the web app; the database adds one read and the guides.
--
-- 1. public.my_trip_photos(): the photo of each car the signed-in renter has a booking for, as one object keyed by the
--    vehicle id. The car's own cover photo (approved, public, not replaced), else its first approved public photo, else
--    the sample photo of its body style (app.vehicle_sample_photos, as the public pages fall back). It reads only the
--    caller's bookings (renter_bookings filters on app.my_renter_id()), so a car that is not listed on the site still
--    shows its photo to the renter who booked it, and nobody else. Read only: no booking, price or payment is touched.
-- 2. The guides: the renter guide's chapters that describe Trips and the booking page.

-- ================================================================ 1. the trip photos
create or replace function public.my_trip_photos() returns jsonb
language sql stable security definer set search_path = public, app as $$
  select coalesce(jsonb_object_agg(t.vehicle_id, t.photo) filter (where t.photo is not null and t.photo <> 'null'::jsonb), '{}'::jsonb)
    from (select v.vehicle_id,
                 coalesce((select jsonb_build_object('path', ph.processed_path, 'variants', ph.variants, 'alt', ph.alt_text)
                             from vehicle_photos ph
                            where ph.vehicle_id = v.vehicle_id and ph.is_public and ph.status = 'approved' and ph.replaced_at is null
                              and ph.processed_path is not null
                            order by ph.is_cover desc, ph.sort_order, ph.created_at
                            limit 1),
                          app.vehicle_sample_photos(v.vehicle_id) -> 0) photo
            from (select distinct rb.vehicle_id from renter_bookings rb where rb.vehicle_id is not null) v) t
$$;
revoke all on function public.my_trip_photos() from public, anon;
grant execute on function public.my_trip_photos() to authenticated, service_role;
comment on function public.my_trip_photos() is
  'The renter portal (0152): the photo of each car the signed-in renter has booked, keyed by vehicle id. Read only.';

